import {writeSync} from 'node:fs';
import {monitorEventLoopDelay} from 'node:perf_hooks';
import {PrintController} from '/home/dek02/.codex/worktrees/moonraker-fixed-bundle-acceptance/ANYRAID-KLIPPER/host/src/operations/print.ts';
import {PrintJournal} from '/home/dek02/.codex/worktrees/moonraker-fixed-bundle-acceptance/ANYRAID-KLIPPER/host/src/operations/print-journal.ts';
const events=[],begin=performance.now(),loop=monitorEventLoopDelay({resolution:1});loop.enable();
const record=(kind,data={})=>events.push({kind,ms:performance.now()-begin,...data});
const observe=(promise,kind,data={})=>{promise.then(()=>record(kind+'-resolved',data),error=>record(kind+'-rejected',{...data,error:error.message}));return promise;};
const transition=PrintJournal.prototype.transition;
PrintJournal.prototype.transition=function(...args){const data={state:args[2],pending:this.pendingRequests};record('journal-transition-called',data);return observe(transition.apply(this,args),'journal-transition',data);};
const cancel=PrintController.prototype.cancel;let cancels=0;
PrintController.prototype.cancel=function(...args){const data={index:++cancels,state:this.state,pendingDeviceActions:this.pendingDeviceActions};record('cancel-called',data);return observe(cancel.apply(this,args),'cancel',data);};
const restore=PrintController.restore;
PrintController.restore=function(device,...args){const stop=device.stop;device.stop=function(...stopArgs){record('device-stop-called');return observe(stop.apply(this,stopArgs),'device-stop');};return restore.call(this,device,...args);};
const timer=setTimeout;
globalThis.setTimeout=function(callback,ms,...args){if(ms!==30)return timer(callback,ms,...args);const scheduled=performance.now();record('deadline-scheduled',{timeoutMs:ms});return timer(function(...values){record('deadline-dispatched',{elapsedMs:performance.now()-scheduled});return callback(...values);},ms,...args);};
process.once('exit',()=>{loop.disable();if(events.length)writeSync(1,JSON.stringify({cancelPhaseDiagnostic:{pid:process.pid,node:process.version,observerScope:'Buffered observations on unchanged test/controller/journal; not a replacement full-suite gate',loopP99Ms:loop.percentile(99)/1e6,loopMaxMs:loop.max/1e6,events}})+'\n');});
